SELECT i.id, i.title, (SELECT img.url FROM item_image img WHERE img.item_id = i.id ORDER BY img.sort_no, img.id LIMIT 1) AS cover_url, i.price, c.name AS category_name, i.seller_id, u.nickname AS seller_nickname, u.auth_status AS seller_auth_status, i.status, i.reject_reason, i.description, i.created_at, i.audit_at, i.listed_at FROM item i JOIN category c ON c.id = i.category_id JOIN sys_user u ON u.id = i.seller_id
AND i.status = #{status}
AND (i.title LIKE CONCAT('%', #{keyword}, '%') ESCAPE '!' OR u.nickname LIKE CONCAT('%', #{keyword}, '%') ESCAPE '!')
ORDER BY i.created_at DESC, i.id DESC LIMIT #{offset}, #{size}

